class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp is a dictionary: key = (current_alternating_sum, next_parity)
        # value = maximum product achievable for that state
        # next_parity: 0 means next element added will be at even index (added to sum)
        #              1 means next element added will be at odd index (subtracted from sum)
        # We only store non-empty subsequences.
        dp = {}

        for x in nums:
            # Create a new_dp as a copy of current dp (this represents skipping x)
            new_dp = dp.copy()

            # Option 1: Start a new subsequence with x
            # This subsequence has one element at index 0 (even), so sum = x, next_parity = 1
            if x <= limit:
                state = (x, 1)
                if state not in new_dp or new_dp[state] < x:
                    new_dp[state] = x

            # Option 2: Extend existing subsequences
            for (s, p), prod in dp.items():
                if p == 0:
                    # Next element is at even index in subsequence, so add x
                    ns = s + x
                    np = 1
                else:
                    # Next element is at odd index in subsequence, so subtract x
                    ns = s - x
                    np = 0

                nprod = prod * x
                if nprod <= limit:
                    state = (ns, np)
                    if state not in new_dp or new_dp[state] < nprod:
                        new_dp[state] = nprod

            dp = new_dp

        # Find the maximum product among all states with alternating sum equal to k
        ans = -1
        for (s, p), prod in dp.items():
            if s == k:
                if prod > ans:
                    ans = prod

        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1

        # DSU class
        class DSU:
            def __init__(self, size):
                self.parent = list(range(size))
                self.rank = [0] * size
                self.forced_char = [None] * size  # The character that this group must be, or None

            def find(self, x):
                if self.parent[x] != x:
                    self.parent[x] = self.find(self.parent[x])
                return self.parent[x]

            def union(self, x, y):
                rx, ry = self.find(x), self.find(y)
                if rx == ry:
                    return
                if self.rank[rx] < self.rank[ry]:
                    rx, ry = ry, rx
                self.parent[ry] = rx
                if self.rank[rx] == self.rank[ry]:
                    self.rank[rx] += 1
                # Merge forced_char: if one is set, the other must match
                if self.forced_char[rx] is None:
                    self.forced_char[rx] = self.forced_char[ry]
                elif self.forced_char[ry] is not None:
                    if self.forced_char[rx] != self.forced_char[ry]:
                        return False  # Contradiction
                return True

            def set_forced(self, x, c):
                r = self.find(x)
                if self.forced_char[r] is None:
                    self.forced_char[r] = c
                elif self.forced_char[r] != c:
                    return False  # Contradiction
                return True

        dsu = DSU(total_len)

        # Process 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                # word[i:i+m] must equal str2
                for j in range(m):
                    idx = i + j
                    # Union all positions in the window
                    if j > 0:
                        if not dsu.union(i + j - 1, idx):
                            return ""
                    # Set the character for this position
                    if not dsu.set_forced(idx, str2[j]):
                        return ""

        # Build the initial word array based on DSU
        # For each group, if forced_char is set, all members get that char.
        # Otherwise, they are free (initially 'a').
        word = [''] * total_len
        for i in range(total_len):
            r = dsu.find(i)
            if dsu.forced_char[r] is not None:
                word[i] = dsu.forced_char[r]
            else:
                word[i] = 'a'  # Default to smallest

        # Now handle 'F' constraints
        # For each i where str1[i] == 'F', we need word[i:i+m] != str2
        # We process from left to right. If a violation is found, we fix it
        # by changing the rightmost unfixed character in the window to the smallest valid char.

        for i in range(n):
            if str1[i] == 'F':
                # Check if current word[i:i+m] equals str2
                # Since m is small (<=500), direct comparison is acceptable here
                # But we need to be careful: we are modifying word as we go.
                # We check the current state of word.
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    # Need to break the match by changing one character in word[i:i+m]
                    # To keep lexicographically smallest, change the rightmost unfixed character
                    # An index k in [i, i+m-1] is "unfixed" if it is not forced by any 'T' constraint.
                    # In our DSU, an index is unfixed if its root's forced_char is None.
                    # But note: we already built the word array. We need to know which positions are fixed.
                    # We can precompute a fixed array.
                    pass

        # Precompute which positions are fixed (forced by 'T' constraints)
        fixed = [False] * total_len
        for i in range(total_len):
            r = dsu.find(i)
            if dsu.forced_char[r] is not None:
                fixed[i] = True

        # Re-process 'F' constraints with the ability to modify word
        for i in range(n):
            if str1[i] == 'F':
                # Check if current word[i:i+m] equals str2
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    # Find the rightmost unfixed index in [i, i+m-1]
                    change_idx = -1
                    for j in range(m - 1, -1, -1):
                        if not fixed[i + j]:
                            change_idx = i + j
                            break
                    if change_idx == -1:
                        # All positions in the window are fixed, and they match str2 -> impossible
                        return ""
                    # Change word[change_idx] to the smallest character that doesn't match str2[change_idx - i]
                    target_char = str2[change_idx - i]
                    # Try 'a', 'b', ... until we find one that is not target_char
                    for c in 'abcdefghijklmnopqrstuvwxyz':
                        if c != target_char:
                            word[change_idx] = c
                            break

        return "".join(word)

import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        X = int(next(iterator))
    except StopIteration:
        return

    vit1_foods = []
    vit2_foods = []
    vit3_foods = []

    for _ in range(N):
        v = int(next(iterator))
        a = int(next(iterator))
        c = int(next(iterator))
        if v == 1:
            vit1_foods.append((a, c))
        elif v == 2:
            vit2_foods.append((a, c))
        else:
            vit3_foods.append((a, c))

    # Binary search for the maximum K
    # K can range from 0 to 5000 (since X <= 5000 and min C_i >= 1)
    low = 0
    high = 5000
    ans = 0

    def check(K):
        if K == 0:
            return True

        INF = float('inf')
        # dp[i][j] = min calories to get at least i Vit1, at least j Vit2
        # Dimensions: (K+1) x (K+1)
        dp = [[INF] * (K + 1) for _ in range(K + 1)]
        dp[0][0] = 0

        # Process Vit1 items
        # For each Vit1 item, update dp[new_i][j] = min(dp[new_i][j], dp[i][j] + c)
        # where new_i = min(i + a, K)
        # Iterate backwards to avoid using the same item multiple times
        for a, c in vit1_foods:
            for i in range(K, -1, -1):
                for j in range(K + 1):
                    if dp[i][j] == INF:
                        continue
                    new_i = i + a
                    if new_i > K:
                        new_i = K
                    new_cost = dp[i][j] + c
                    if new_cost < dp[new_i][j]:
                        dp[new_i][j] = new_cost

        # Process Vit2 items
        # For each Vit2 item, update dp[i][new_j] = min(dp[i][new_j], dp[i][j] + c)
        # where new_j = min(j + a, K)
        # Iterate backwards
        for a, c in vit2_foods:
            for j in range(K, -1, -1):
                for i in range(K + 1):
                    if dp[i][j] == INF:
                        continue
                    new_j = j + a
                    if new_j > K:
                        new_j = K
                    new_cost = dp[i][j] + c
                    if new_cost < dp[i][new_j]:
                        dp[i][new_j] = new_cost

        # Step 2: Compute min_cal_v3[k] = min calories to get at least k units of Vit3
        # This is a 1D knapsack
        min_cal_v3 = [INF] * (K + 1)
        min_cal_v3[0] = 0

        for a, c in vit3_foods:
            # Update min_cal_v3: for k from K down to 0
            for k in range(K, -1, -1):
                if min_cal_v3[k] == INF:
                    continue
                new_k = k + a
                if new_k > K:
                    new_k = K
                new_cost = min_cal_v3[k] + c
                if new_cost < min_cal_v3[new_k]:
                    min_cal_v3[new_k] = new_cost

        # Step 3: Check if there exists i>=K, j>=K such that dp[i][j] + min_cal_v3[K] <= X
        # Since we capped indices at K, dp[K][K] represents the min calories to get
        # at least K Vit1 and at least K Vit2.
        # We need at least K Vit3 as well, which costs min_cal_v3[K].

        if dp[K][K] == INF or min_cal_v3[K] == INF:
            return False

        return dp[K][K] + min_cal_v3[K] <= X

    # Binary search
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Helper function to check if a given max_length L is feasible
        def is_feasible(L: int) -> bool:
            if L <= 0:
                return False
            ops_needed = 0
            # Iterate through the string to find runs of identical characters
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                run_length = j - i
                # For a run of length k, flips needed is max(0, (k - 1) // L)
                if run_length > L:
                    ops_needed += (run_length - 1) // L
                i = j
                # Early termination if ops_needed exceeds numOps
                if ops_needed > numOps:
                    return False
            return ops_needed <= numOps

        # Binary search for the minimum possible maximum length
        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if is_feasible(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    N = int(next(iterator))
    X = int(next(iterator))

    A = [int(next(iterator)) for _ in range(N)]
    B = [int(next(iterator)) for _ in range(N)]
    P = [int(next(iterator)) for _ in range(N)]
    Q = [int(next(iterator)) for _ in range(N)]

    # Convert to 0-indexed internally for boxes 0 to N-1
    # X is given as 1-indexed, convert to 0-indexed
    X0 = X - 1

    # If no balls at all, answer is 0
    if all(a == 0 for a in A) and all(b == 0 for b in B):
        print(0)
        return

    # Build reverse graphs for red and blue
    # rev_red[i] contains list of j such that P[j] == i+1 (in 1-indexed) -> in 0-indexed: P[j] == i
    rev_red = [[] for _ in range(N)]
    for i in range(N):
        p_val = P[i] - 1  # 0-indexed target
        rev_red[p_val].append(i)

    rev_blue = [[] for _ in range(N)]
    for i in range(N):
        q_val = Q[i] - 1  # 0-indexed target
        rev_blue[q_val].append(i)

    # BFS from X0 in rev_red to get R_set: all nodes that can reach X0 in red graph
    R_set = set()
    queue = deque([X0])
    R_set.add(X0)
    while queue:
        node = queue.popleft()
        for neighbor in rev_red[node]:
            if neighbor not in R_set:
                R_set.add(neighbor)
                queue.append(neighbor)

    # BFS from X0 in rev_blue to get B_set
    B_set = set()
    queue = deque([X0])
    B_set.add(X0)
    while queue:
        node = queue.popleft()
        for neighbor in rev_blue[node]:
            if neighbor not in B_set:
                B_set.add(neighbor)
                queue.append(neighbor)

    # Check if all initial red balls can reach X0
    for i in range(N):
        if A[i] == 1:
            if i not in R_set:
                print(-1)
                return

    # Check if all initial blue balls can reach X0
    for i in range(N):
        if B[i] == 1:
            if i not in B_set:
                print(-1)
                return

    # Now, collect all boxes that need to be operated on (excluding X0)
    S = set()

    # For red balls
    for i in range(N):
        if A[i] == 1:
            j = i
            while j != X0:
                if j in S:
                    break
                S.add(j)
                j = P[j] - 1  # move to next box in red path (0-indexed)

    # For blue balls
    for i in range(N):
        if B[i] == 1:
            j = i
            while j != X0:
                if j in S:
                    break
                S.add(j)
                j = Q[j] - 1  # move to next box in blue path (0-indexed)

    print(len(S))

if __name__ == '__main__':
    main()

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Union-Find data structure
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # Path compression
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # Union by rank
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Create a set for O(1) lookup and a mapping from value to index
        num_set = set(nums)
        val_to_idx = {val: i for i, val in enumerate(nums)}

        # For each number in nums, iterate over its multiples up to threshold
        # If a multiple exists in nums, union the two indices
        for a in nums:
            # If a > threshold, it can't form any edge because lcm(a, b) >= a > threshold
            if a > threshold:
                continue
            # Iterate over multiples: a*2, a*3, ... up to threshold
            # Start from k=2 because k=1 is the same element
            k = 2
            while k * a <= threshold:
                m = k * a
                if m in num_set:
                    # Union the indices of a and m
                    idx_a = val_to_idx[a]
                    idx_m = val_to_idx[m]
                    union(idx_a, idx_m)
                k += 1

        # Count the number of unique roots
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
